package com.fromscratch.persistence;

import com.fromscratch.SnapshotFixtures;
import com.fromscratch.bank.*;
import com.fromscratch.buyback.*;
import com.fromscratch.model.ContainerSnapshot;
import com.google.gson.*;
import java.io.IOException;
import java.util.*;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.util.Filepath;
import org.junit.*;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;

/** New per-copy evidence and actual forced publication, portable backup, and old-checkpoint compatibility. */
public class SelectedBuybackPersistenceTest
{
	@Rule public TemporaryFolder temp=new TemporaryFolder();private Filepath root;private BankRunCodec codec;private BankRepository repository;
	private static final int MASK=ItemID.HARMLESS_BLACK_MASK;
	@Before public void setup()throws Exception{root=Filepath.Unchecked.getRooted(temp.newFolder("store").toPath());codec=new BankRunCodec(SnapshotFixtures.gson());repository=new BankRepository(codec,SnapshotFixtures.codec());}
	private BankRun active()throws Exception{BankRun initial=BankEngine.start(SnapshotFixtures.CHARACTER_A,null,BuybackModelTest.bank(MASK,MASK,ItemID.TZHAAR_CAPE_FIRE),true,UUID.randomUUID(),SnapshotFixtures.TIME);repository.save(root,null,initial);Map<Integer,Long> bank=new TreeMap<>(initial.getPhysical());bank.put(ItemID.COINS,4000000L);return repository.save(root,initial,BankEngine.observe(initial,new ContainerSnapshot(bank,bank.size()),UUID.randomUUID(),SnapshotFixtures.TIME));}
	private BankRun next(BankRun before){return BankEngine.buySelected(before,"slayer_gear",MASK,UUID.randomUUID(),UUID.randomUUID(),SnapshotFixtures.TIME);}
	private BankRun load()throws Exception{return repository.load(root,SnapshotFixtures.CHARACTER_A).get();}
	@Test public void selectedCopyReceiptHasDedicatedExactIdentityAndQuantity()throws Exception{BankRun r=next(active());BuybackPurchase p=r.getBuybacks().getPurchases().get(0);JsonObject json=BuybackCodec.purchase(p);assertFalse(json.has("pouch"));assertFalse(json.has("bag"));assertEquals(MASK,json.getAsJsonObject("selected").get("item").getAsInt());assertEquals(1,json.getAsJsonObject("selected").get("quantity").getAsInt());assertEquals(p,BuybackCodec.purchase(json));assertEquals(r,codec.decode(codec.encode(r),r.getCharacter()));}
	@Test public void twoCopiesSurviveFullRepositoryRestartAndBackupRestore()throws Exception{BankRun r=active();r=repository.save(root,r,next(r));r=repository.save(root,r,next(r));BankRun paid=r;assertEquals(2L,(long)BuybackEngine.balances(load()).get(MASK));Filepath exported=Filepath.Unchecked.getRooted(temp.getRoot().toPath().resolve("synthetic.fsp"));repository.backups().exportProgress(root,r,exported);r=repository.save(root,r,BankEngine.correct(r,MASK,-1,UUID.randomUUID(),SnapshotFixtures.TIME));ProgressBackup.Candidate backup=repository.backups().preview(root,r.getCharacter(),exported);assertEquals(paid,backup.getRun());repository.backups().restore(root,backup);assertEquals(paid,load());assertEquals(2000000,load().getBuybacks().getCommittedGp());}
	@Test public void failedPublicationAndLostAcknowledgmentAreSafeAndIdempotent()throws Exception{BankRun before=active(),after=next(before);BankRepository bad=new BankRepository(codec,SnapshotFixtures.codec(),(a,b)->{throw new IOException("Synthetic interrupted publication");});try{bad.save(root,before,after);fail();}catch(SaveException expected){}assertEquals(before,load());assertEquals(after,repository.save(root,before,after));assertEquals(after,repository.save(root,before,after));assertEquals(1000000,load().getBuybacks().getCommittedGp());}
	@Test public void oldReceiptAndNewReceiptRetainDistinctMeanings()throws Exception{BankRun before=active();before=repository.save(root,before,BuybackModelTest.buy(before,"fire_cape"));JsonObject old=BuybackCodec.purchase(before.getBuybacks().getPurchases().get(0));BankRun after=repository.save(root,before,next(before));assertEquals(old,BuybackCodec.purchase(load().getBuybacks().getPurchases().get(0)));assertEquals(2,after.getBuybacks().getPurchases().size());assertEquals(1L,(long)BuybackEngine.balances(after).get(ItemID.TZHAAR_CAPE_FIRE));}
	@Test public void formatTenRemainsReadableAndOriginalBytesAreNotRewrittenOnLoad()throws Exception{BankRun r=active();Filepath d=root.join("characters",r.getCharacter()),current=d.joinSegment("current.json"),ledger=d.joinSegment("bank-ledger-"+r.getRevision()+".json");JsonObject data=codec.payload(BankStorageFiles.readText(current),BankRunCodec.FORMAT);String old=codec.envelope(data,10);current.write(old);JsonObject journal=codec.payload(BankStorageFiles.readText(ledger),1);journal.addProperty("result",SaveIntegrity.sha256(old));ledger.write(codec.envelope(journal,1));assertEquals(r,load());assertEquals(old,BankStorageFiles.readText(current));BankRun paid=repository.save(root,r,next(r));assertEquals(paid,load());assertEquals(11,new JsonParser().parse(BankStorageFiles.readText(current)).getAsJsonObject().get("formatVersion").getAsInt());assertEquals(old,BankStorageFiles.readText(d.joinSegment("previous.json")));}
	@Test public void malformedSelectedEvidenceCannotGrantEntitlements()throws Exception
	{
		BuybackPurchase p=next(active()).getBuybacks().getPurchases().get(0);JsonObject original=BuybackCodec.purchase(p);
		for(String fault:new String[]{"quantity","unknown","differentCatalog","missing","wrongFloor","storage"}){JsonObject bad=original.deepCopy();switch(fault){case "quantity":bad.getAsJsonObject("selected").addProperty("quantity",2);break;case "unknown":bad.getAsJsonObject("selected").addProperty("item",ItemID.WOODEN_SHIELD);break;case "differentCatalog":bad.addProperty("catalog","elite_black_helm");break;case "missing":bad.remove("selected");break;case "wrongFloor":bad.getAsJsonObject("floors").addProperty("copy_"+ItemID.SLAYER_HELM,0);break;case "storage":bad.add("bag",new JsonObject());break;}try{BuybackCodec.purchase(bad);fail(fault);}catch(IllegalArgumentException expected){}}
	}
	@Test public void mismatchedTotalsCountsAndDuplicateReceiptsAreRejected()throws Exception{BankRun r=next(active());BuybackState s=r.getBuybacks();for(String field:new String[]{"gp","count","duplicate"}){JsonObject bad=BuybackCodec.state(s);if(field.equals("gp")){bad.addProperty("committedGp",999999);}else if(field.equals("count")){bad.getAsJsonObject("roles").getAsJsonObject(SelectedBuybacks.role(MASK)).addProperty("quantity",2);}else{bad.getAsJsonArray("purchases").add(bad.getAsJsonArray("purchases").get(0).deepCopy());}try{BuybackCodec.state(bad);fail(field);}catch(IllegalArgumentException expected){}}}
	@Test public void newEvidenceCannotBeDisguisedAsAnOldFormat()throws Exception{BankRun r=next(active());JsonObject payload=codec.payload(codec.encode(r),BankRunCodec.FORMAT);try{codec.decode(codec.envelope(payload,10),r.getCharacter());fail();}catch(SaveException expected){}}
	@Test public void reviewedAllowlistIncludesModernCosmeticsAndRejectsArbitraryTradeables(){assertEquals(104,SelectedBuybacks.items("slayer_gear").size());assertEquals("slayer_gear",SelectedBuybacks.catalog(ItemID.LEAGUE_6_SLAYER_HELM1));assertEquals("slayer_gear",SelectedBuybacks.catalog(ItemID.SLAYER_HELM_VERZIK));assertEquals(29560,ItemID.ELITE_BLACK_FULL_HELM);assertEquals(29562,ItemID.ELITE_BLACK_PLATEBODY);assertEquals(29564,ItemID.ELITE_BLACK_PLATELEGS);int exceptions=0;for(int id:SelectedBuybacks.items("slayer_gear")){if(SelectedBuybacks.tradeableException(id)){exceptions++;}}assertEquals(11,exceptions);assertFalse(SelectedBuybacks.tradeableException(ItemID.SLAYER_HELM));assertFalse(SelectedBuybacks.tradeableException(ItemID.COINS));assertNull(SelectedBuybacks.catalog(ItemID.COINS));assertTrue(SelectedBuybacks.items("diary").isEmpty());}
	@Test public void wrongCharacterCannotDecodeSelectedProgress()throws Exception{BankRun r=next(active());try{codec.decode(codec.encode(r),SnapshotFixtures.CHARACTER_B);fail();}catch(SaveException expected){}}
}
